// utils -> extractLdSchema.ts
import { isArray, isObject, isString } from "../../deps/jsr.io/@pwshub/bellajs/13.1.1/mod.js";
const typeSchemas = [
    "aboutpage",
    "checkoutpage",
    "collectionpage",
    "contactpage",
    "faqpage",
    "itempage",
    "medicalwebpage",
    "profilepage",
    "qapage",
    "realestatelisting",
    "searchresultspage",
    "webpage",
    "website",
    "article",
    "advertisercontentarticle",
    "newsarticle",
    "analysisnewsarticle",
    "askpublicnewsarticle",
    "backgroundnewsarticle",
    "opinionnewsarticle",
    "reportagenewsarticle",
    "reviewnewsarticle",
    "report",
    "satiricalarticle",
    "scholarlyarticle",
    "medicalscholarlyarticle",
];
const attributeLists = {
    description: "description",
    image: "image",
    author: "author",
    published: "datePublished",
    type: "@type",
};
const parseJson = (text) => {
    try {
        return JSON.parse(text);
    }
    catch {
        return {};
    }
};
const isAllowedLdJsonType = (ldJson) => {
    const rootLdJsonType = ldJson["@type"] || "";
    const arr = isArray(rootLdJsonType)
        ? rootLdJsonType
        : [rootLdJsonType];
    const ldJsonTypes = arr.filter((x) => !!x);
    return ldJsonTypes.length > 0 &&
        ldJsonTypes.some((x) => typeSchemas.includes(x.toLowerCase()));
};
export default (document, entry) => {
    const ldSchemas = document.querySelectorAll('script[type="application/ld+json"]');
    ldSchemas.forEach((ldSchema) => {
        const ldJson = parseJson(ldSchema.textContent.replace(/[\n\r\t]/g, ""));
        if (ldJson && isAllowedLdJsonType(ldJson)) {
            for (const [key, attr] of Object.entries(attributeLists)) {
                if (entry[key] || !ldJson[attr]) {
                    continue;
                }
                const keyValue = ldJson[attr];
                const val = isArray(keyValue)
                    ? keyValue[0]
                    : isObject(keyValue)
                        ? keyValue?.name || ""
                        : keyValue;
                if (isString(val) && val !== "") {
                    entry[key] = val.trim();
                }
            }
        }
    });
    return entry;
};
